insert into public.questions (question_id,paper_id,question_number,question_type,question_points,question_text,option_a,option_b,option_c,option_d,option_e,subject_primary,subsubject_primary,subject_secondary,chapter,topic_primary,topic_secondary,law_refs,tags,source_page_start,source_page_end,extraction_status,review_status,notes,is_published) values
('105-2301-001','105-2301',1,'single_choice',2,'甲政黨執政期間推行核能發電，立法院通過預算興建A 核能電廠。乙政黨以反核為主要政見，其總 統候選人當選後欲停建A 核能電廠。依照司法院釋字第520 號，下列何種方式為合法？','由總統逕行宣布停建，行政院即可停止執行A 核能電廠預算','由行政院院長逕行宣布停建，行政院即可停止執行A 核能電廠預算','由總統召集五院院長會商後，行政院即可停止執行A 核能電廠預算','由行政院院長或有關部會首長向立法院提出報告並備質詢，經立法院同意，行政院即可停止執行 A 核能電廠預算',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('105-2301-002','105-2301',2,'single_choice',2,'承上題，甲政黨不同意行政院停建A 核能電廠，發動其黨籍立法委員全面杯葛、癱瘓立法院議事，總 統對於該杯葛行為極度不滿，其所採下列手段何者為合法？','透過乙政黨動員選民，在甲政黨立法委員選區發動罷免擁核立法委員','總統主動解散立法院，由選民決定是否繼續興建A 核能電廠','總統指示中央選舉委員會舉辦重大政策公投，由公民決定是否繼續興建A 核能電廠','總統命立法院對行政院院長進行信任投票，如不獲通過，總統將解散立法院，由選民決定是否繼 續興建A 核能電廠',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('105-2301-003','105-2301',3,'single_choice',2,'承上題，甲政黨立法委員對於乙政黨總統極度不滿，其所採手段下列何種合法？','經全體立法委員三分之一之提議總統、副總統罷免案，全體立法委員三分之二之同意後提出，並 經中華民國自由地區選舉人總額過半數之投票，有效票過半數同意罷免之','經全體立法委員四分之一之提議總統、副總統罷免案，全體立法委員三分之二之同意後提出，並 經中華民國自由地區選舉人有效同意票過選舉人總額之半數同意罷免之','由立法院向監察院提出總統、副總統彈劾案。如監察院議決彈劾案成立時，乙政黨總統、副總統 應即解職','由立法院提出總統、副總統彈劾案，聲請司法院大法官審理。如憲法法庭判決成立時，乙政黨總 統、副總統應即解職',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],1,1,'parsed','pending_manual_review',null,true),
('105-2301-004','105-2301',4,'single_choice',2,'下列有關職業自由之敘述，何者正確？','職業自由之權利保障內容，包括從事工作之方法、時間、地點等執行職業之自由，立法者為追求 一般公共利益，非不得予以適當之限制','人民選擇職業之自由，如屬應具備之主觀條件，例如知識、學位、體能等，立法者欲對此加以限 制，至少須有一般公共利益存在','人民選擇職業應具備之客觀條件，係指對從事特定職業之條件限制，非個人努力所可達成，則該 限制應以保護重要之公共利益始得為之','對於職業自由之限制，只有限制所謂執行職業之自由時，所採取之手段必須符合比例原則之要求',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('105-2301-005','105-2301',5,'single_choice',2,'下列關於言論自由之敘述，何者錯誤？','有人以焚燒他國國旗抗議其壓迫人權，此行為受言論自由所保障','政治性言論屬於低價值的言論','言論自由除保障積極之表意自由外，尚保障消極之不表意自由','言論自由保障的目的之一為實現自我',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('105-2301-006','105-2301',6,'single_choice',2,'就我國現行選舉制度而言，直轄市長選舉時，除了被剝奪選舉權者外，選舉人欲進行投票，必須攜 帶身分證與投票通知單到指定地點，且只能領取一張選票。該敘述涉及我國憲法第129 條的何種選 舉原則？','普通、平等、直接','普通、秘密、直接','秘密、平等、直接','普通、平等、秘密',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('105-2301-007','105-2301',7,'single_choice',2,'下列有關大法官對平等原則或平等權之解釋要旨，何者錯誤？','憲法第7 條所定之平等權，禁止法律授權主管機關，斟酌具體案件及立法目的，而為合理之不同 處置','憲法第7 條平等原則，係保障人民在法律上地位之實質平等','政黨推薦之公職人員選舉候選人，保證金可減半繳納之規定，無異使無政黨推薦之候選人，須繳 納較高額之保證金，形成不合理之差別待遇，與憲法第7 條之意旨有違','不起訴處分確定前或後，受羈押之人民，與受無罪判決確定前曾受羈押而喪失自由者，權利均遭 受同等損害，亦應享有回復利益，立法者對之漏未規定，足以形成人民在法律上之不平等，與憲 法第7 條有所牴觸',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('105-2301-008','105-2301',8,'single_choice',2,'大法官的權限不包含下列何者？','解釋憲法','統一解釋法律及命令','審理法官彈劾事項','審理政黨解散事項',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('105-2301-009','105-2301',9,'single_choice',2,'有關權力分立原則，下列敘述何者正確？','對於我國憲法五權分立中的各個權力部門間之互動關係的理解，應採取完全無相互制衡之詮釋方 式為當','審判獨立乃權力分立與制衡之重要原則','權力分立的目的就是要建立大有為的行政權','權力分立思想與儒家思想不謀而合',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('105-2301-010','105-2301',10,'single_choice',2,'下列有關總統依據憲法增修條文第2 條第3 項發布緊急命令之敘述，何者錯誤？','須經行政院院會之決議','於發布命令後10 日內提交立法院追認','立法院同意後，該緊急命令開始生效','依據司法院大法官解釋，其內容應力求周延，以不得再授權為補充規定即可逕予執行為原則',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('105-2301-011','105-2301',11,'single_choice',2,'依臺灣地區與大陸地區人民關係條例第21 條第1 項前段規定，大陸地區人民經許可進入臺灣地區者， 非在臺灣地區設有戶籍滿10 年，不得擔任公教人員。甲之配偶乙原為大陸地區人民，在臺灣地區設 籍未滿10 年，甲認為系爭規定侵害平等權。依司法院釋字第618 號解釋，下列敘述何者正確？','在臺灣地區之大陸地區人民不受憲法基本權保障','乙不得主張平等權保護','系爭規定以10 年為期，其手段仍在必要及合理之範圍內，立法者就此所為之斟酌判斷，尚無明顯 而重大之瑕疵','對大陸地區人民所為之差別待遇，必須是為追求特別重要的公共利益，且沒有其他侵害較小的手 段，始能通過憲法保障平等權的嚴格審查',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('105-2301-012','105-2301',12,'single_choice',2,'司法院大法官曾就下列何種事項要求行政機關在作成行政決定之前，必須舉辦聽證，使利害關係人 得到場以言詞為意見之陳述及論辯，始符合憲法正當法律程序原則之要求？','行政機關對都市更新事業計畫之核定','公立大學對大學生作成退學處分','部隊對於不符軍事紀律士兵所為之關禁閉處分','衛生主管機關對於疑似感染狂犬病患者為隔離處分',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('105-2301-013','105-2301',13,'single_choice',2,'直轄市制定自治條例，因涉及罰則而報請行政院核定，但行政院認此自治條例有違憲之虞。下列敘 述何者正確？','行政院得向大法官聲請解釋該自治條例為違憲','該直轄市的議會得向大法官聲請解釋該自治條例為違憲','該直轄市對行政院的「拒絕核定」，得向大法官聲請釋憲','該直轄市對行政院的拒絕核定應先提起行政爭訟，待確定終局裁判後主張其基本權利受侵害而聲 請釋憲',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('105-2301-014','105-2301',14,'single_choice',2,'下列何種行政措施不適用法律保留原則？','限制人民基本權利時','雖未限制基本權利，但涉及重大公共利益時','雖未限制基本權利，但涉及實現人民基本權利之保障等重大事項時','涉及執行法律之技術性、細節性次要事項',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('105-2301-015','105-2301',15,'single_choice',2,'下列何者並非行政罰法第14 條所稱故意共同實施違反行政法上義務之行為？','不具公務員身分之甲與具公務員身分之配偶乙共同為不實之公務員財產申報行為','自然人丙違法傾倒廢棄物，朋友丁提供機具並在現場把風','A 公司與B 公司共同埋設暗管排放廢水','C 公司之職員戊違法為C 公司聘用外籍勞工',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('105-2301-016','105-2301',16,'single_choice',2,'下列訴願之提起，何者為合法？','妻因違反廢棄物清理法而受罰鍰處分，夫主張其財產權被侵害，以自己名義提起訴願','公司受罰鍰處分，其董事長主張其財產權被侵害，以自己名義提起訴願','子因學業成績不佳受退學處分，其父主張其名譽權被侵害，以自己名義提起訴願','建築主管機關核發甲建築執照，其鄰地所有人主張其日照權被侵害，以自己名義提起訴願',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('105-2301-017','105-2301',17,'single_choice',2,'下列那一種行政處分之附款不影響行政處分的效力？','期限','停止條件','負擔','解除條件',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('105-2301-018','105-2301',18,'single_choice',2,'下列那一種法規範，並非由行政機關所訂定？','行政程序法之行政規則','地方制度法之自治規則','地方制度法之委辦規則','地方制度法之自律規則',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('105-2301-019','105-2301',19,'single_choice',2,'郵政機關送達行政處分書，於105 年1 月2 日於應送達處所不獲會晤被處分人A。雖A 有就讀於大 學之子女B 同住於一處，但郵政機關仍逕行作成送達證書，並將該文書寄存於郵局。3 個月後，郵 政機關將文書退回原處分機關。至同年5 月2 日原處分機關再為送達，同日A 取得該文書。本件送 達之效力應於何日發生？','同年1 月2 日','同年1 月3 日','同年5 月2 日','同年5 月3 日',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('105-2301-020','105-2301',20,'single_choice',2,'當人民欲尋求暫時性權利保護時，下列何種情形不適用行政處分停止執行制度，而應向行政法院聲 請定暫時狀態之處分？','當事人不服主管機關下命沒入違禁品之行政處分','當事人欲參加國家考試，其報名被拒絕','主管機關核准A 公司取得商標權，B 公司對此不服','當事人認為某行政處分無效，提起行政處分無效確認之訴',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('105-2301-021','105-2301',21,'single_choice',2,'在國家賠償事件，於人民與賠償義務機關協議不成立後，人民單獨請求損害賠償時，依現行法制， 應循何種救濟管道？','聲請非訟事件上之裁定','提起民事訴訟','提起行政訴訟','提起刑事訴訟',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('105-2301-022','105-2301',22,'single_choice',2,'經濟部依公司法第5 條第2 項將其處理A 縣境內有關公司之事項委由A 縣政府辦理。今A 縣政府的 公務員甲故意對乙公司作成違法命其解散之處分，該處分事後雖經訴願決定撤銷，惟已造成乙公司 新臺幣1 千多萬元的損害。對於乙公司之損害，何者應負賠償責任？','由經濟部單獨負賠償責任','由甲單獨負賠償責任','由經濟部與甲連帶負賠償責任','由A 縣政府單獨負賠償責任',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],4,4,'parsed','pending_manual_review',null,true),
('105-2301-023','105-2301',23,'single_choice',2,'承上題，若A 縣政府於99 年3 月2 日作成處分，99 年6 月3 日處分經訴願決定撤銷。設乙公司於 99 年7 月6 日知有損害，則乙公司應於那一期日之前，向賠償義務人請求國家賠償？','101 年3 月2 日','101 年7 月6 日','101 年6 月3 日','104 年3 月2 日',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('105-2301-024','105-2301',24,'single_choice',2,'軍事設施擴建時，部分軍事設施佔用到私人甲之土地，甲請求拆除該部分設施遭拒絕，其救濟管道 為何？','甲可以提起訴願，若未獲救濟，可提起撤銷拒絕處分之訴訟','甲可以提起訴願，若未獲救濟，可提起課予拆除義務之訴訟','甲可以提起一般給付訴訟，請求除去因違法佔用造成之事實結果','甲可提起確認佔用行為違法之訴訟',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
('105-2301-025','105-2301',25,'single_choice',2,'下列有關一般給付訴訟之敘述，何者錯誤？','一般給付訴訟不限於人民擔任原告，行政機關亦得擔任此類訴訟之原告','甲依行政機關命其給付新臺幣10 萬元之行政處分而已為給付，但認為該行政處分違法，原則上得 提起一般給付訴訟，請求返還','行政機關發布某類食品之檢驗報告，A 廠商認為該份報告內容不實損及其商譽，其得提起一般給 付訴訟請求行政機關撤回或更正所發布之訊息','人民若欲請求行政機關未來「不作成」某項行政處分，得提起一般給付訴訟',null,'行政法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],5,5,'parsed','pending_manual_review',null,true),
